import json,glob,collections
for f in glob.glob('logs/rollout_timing/rollout_*.json'):
 x=json.load(open(f)); rows=x.get('groups',[]); c=collections.Counter()
 for r in rows:
  if r.get('rewards'):
   c['accepted' if r.get('keep') else r.get('reason','rej')]+=1
 print(f,c)
